contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 d, uint256 a) internal {
        vm.assume(true);
        try c.AdjustDifficulty(d) {} catch { return; }
        try c.AdjustBetAmounts(a) {} catch { return; }
        uint256 diff;
        try c.currentDifficulty() returns (uint256 __r) { diff = __r; } catch { return; }
        uint256 limit;
        try c.currentBetLimit() returns (uint256 __r) { limit = __r; } catch { return; }
        assertTrue(diff == d && limit == a);
    }

    function testFuzz_run(uint256 d, uint256 a) public {
        _run(d, a);
    }

    receive() external payable {}
